import { useEffect, useState } from "react";
import type { FormEvent } from "react";
import { Bell, ChevronDown, CircleDollarSign, ClipboardList, CreditCard, FileText, FolderOpen, LayoutDashboard, LogOut, Menu, MessageSquare, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Users, X } from "lucide-react";
import { getNeonToken, neonClient, neonConfigured } from "./lib/neon";
import "./App.css";

type ProjectStatus = "discovery" | "design" | "development" | "testing" | "client_review" | "final_delivery" | "completed";
const statusOrder: ProjectStatus[] = ["discovery", "design", "development", "testing", "client_review", "final_delivery", "completed"];
const statusLabel: Record<ProjectStatus, string> = { discovery: "Discovery", design: "Design", development: "Development", testing: "Testing", client_review: "Client Review", final_delivery: "Final Delivery", completed: "Completed" };
type Project = { id: string; name: string; status: ProjectStatus; progress: number; total_price: number | string; monthly_minimum?: number | string; currency: string; company_name?: string; amount_paid?: number | string; remaining_balance?: number | string; due_date?: string | null };
type Payment = { id: string; project_id: string; amount: number | string; currency: string; paid_at: string; method: string; reference?: string; note?: string; project_name: string; company_name: string; monthly_minimum?: number | string };
type PaymentSummary = { total_paid: number | string; monthly_minimum: number | string; total_value: number | string; total_remaining: number | string };
type Invoice = { id: string; project_id: string; number: string; amount: number | string; status: string; due_date: string; issued_at: string; paid_at?: string | null; project_name: string; currency: string; company_name: string; customer_name: string; customer_email: string; customer_phone?: string };
type Milestone = { id: string; project_id: string; title: string; description?: string; due_date?: string | null; status: string; approved_at?: string | null; change_request?: string | null; completed_at?: string | null };
type Activity = { id: string; kind: string; title: string; body?: string | null; created_at: string; actor_name?: string };
type Client = { id: string; company_name: string; phone?: string; notes?: string; user_id?: string; email: string; name: string; project_count?: number };
type Approval = { id: string; project_id: string; title: string; document_type: string; content?: string; content_html?: string; content_hash: string; terms_version?: string; legal_notice?: string; read_confirmed_at?: string | null; status: "pending" | "approved" | "revoked"; requested_at: string; approved_at?: string | null; approved_by_name?: string | null; approved_by_email?: string | null; approval_hash?: string | null; project_name?: string; company_name?: string };

async function apiFetch(path: string, init: RequestInit = {}) { const token = await getNeonToken(); return fetch(path, { ...init, headers: { ...(init.headers || {}), ...(token ? { Authorization: `Bearer ${token}` } : {}) } }); }
const UI_LABELS: Record<string, { en: string; tr: string }> = { Dashboard: { en: "Dashboard", tr: "Panel" }, Projects: { en: "Projects", tr: "Projeler" }, Payments: { en: "Payments", tr: "Ödemeler" }, Invoices: { en: "Invoices", tr: "Faturalar" }, Files: { en: "Files", tr: "Dosyalar" }, Messages: { en: "Messages", tr: "Mesajlar" }, Profile: { en: "Profile", tr: "Profil" }, Overview: { en: "Overview", tr: "Genel Bakış" }, Clients: { en: "Clients", tr: "Müşteriler" }, Activity: { en: "Activity", tr: "Aktiviteler" }, Settings: { en: "Settings", tr: "Ayarlar" }, Approvals: { en: "Approvals", tr: "Onaylar" } };
function uiLabel(label: string, language: "en" | "tr") { return UI_LABELS[label]?.[language] || label; }
function markdownPreview(markdown: string) { const escape = (value: string) => value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[character] || character)); let list = false; let html = ""; for (const raw of markdown.replace(/\r\n/g, "\n").split("\n")) { const line = raw.trim(); if (!line) { if (list) { html += "</ul>"; list = false; } continue; } const value = escape(line).replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>").replace(/__([^_]+)__/g, "<strong>$1</strong>").replace(/\*([^*]+)\*/g, "<em>$1</em>"); const heading = value.match(/^(#{1,3})\s+(.+)$/); const bullet = value.match(/^[-*]\s+(.+)$/); if (heading) { if (list) { html += "</ul>"; list = false; } html += `<h${heading[1].length}>${heading[2]}</h${heading[1].length}>`; } else if (bullet) { if (!list) { html += "<ul>"; list = true; } html += `<li>${bullet[1]}</li>`; } else { if (list) { html += "</ul>"; list = false; } html += `<p>${value}</p>`; } } if (list) html += "</ul>"; return html || "<p>Preview will appear here.</p>"; }

const WHATSAPP_NUMBER = "905442577760";
function openWhatsApp(message: string) { window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer"); }

function SkeletonBlock({ className = "" }: { className?: string }) { return <span className={`skeleton-block ${className}`} aria-hidden="true" />; }
function SkeletonDashboard({ full = false }: { full?: boolean }) { if (full) return <div className="skeleton-full"><div className="skeleton-brand"><span className="skeleton-mark">H</span><SkeletonBlock className="skeleton-line short" /></div><SkeletonBlock className="skeleton-line title" /><SkeletonBlock className="skeleton-line medium" /><div className="skeleton-loader-label">LOADING HERMES PORTAL<span>_</span></div></div>; return <div className="skeleton-dashboard" aria-label="Loading"><div className="skeleton-hero"><div><SkeletonBlock className="skeleton-line tiny" /><SkeletonBlock className="skeleton-line hero-title" /><SkeletonBlock className="skeleton-line medium" /></div><SkeletonBlock className="skeleton-button" /></div><div className="skeleton-grid"><div className="skeleton-card dark"><SkeletonBlock className="skeleton-line tiny" /><SkeletonBlock className="skeleton-line number" /><SkeletonBlock className="skeleton-bar" /></div><div className="skeleton-card"><SkeletonBlock className="skeleton-line tiny" /><SkeletonBlock className="skeleton-line price" /><SkeletonBlock className="skeleton-line medium" /><SkeletonBlock className="skeleton-line medium" /></div></div><div className="skeleton-card table"><SkeletonBlock className="skeleton-line medium" />{[1,2,3,4].map((row) => <div className="skeleton-row" key={row}><SkeletonBlock /><SkeletonBlock /><SkeletonBlock className="short" /></div>)}</div></div>; }

function BrandMark({ small = false }: { small?: boolean }) { return <span className={`brand-mark${small ? " small" : ""}`}><img src="/hermes-mark.svg" alt="Hermes Software" /></span>; }
function DemoLogin() {
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  async function submit(event: FormEvent) { event.preventDefault(); if (!neonClient) return; setLoading(true); setError(""); const result = await neonClient.auth.signIn.email({ email, password }); setLoading(false); if (result.error) setError(result.error.message || "Authentication failed"); else window.location.reload(); }
  return <div className="login-shell"><form className="login-card" onSubmit={submit}><BrandMark /><p className="eyebrow">HERMES SOFTWARE / CLIENT PORTAL</p><h1>Good work<br /><span>ships together.</span></h1><p className="muted">A private workspace for project progress, files, invoices and the next move.</p><label className="login-label">EMAIL<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} required placeholder="you@company.com" /></label><label className="login-label">PASSWORD<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} required minLength={8} placeholder="••••••••" /></label>{error && <p className="login-error">{error}</p>}<button className="button button-green wide" disabled={loading}>{loading ? "CONNECTING…" : "ENTER PORTAL"} <ChevronDown size={16} /></button><p className="login-invite-note">Client access is invite-only. Ask Hermes Software to create your account.</p><small>Protected by Neon Managed Auth · Better Auth</small></form></div>;
}

function ActivationPage() { const token = new URLSearchParams(window.location.search).get("token") || ""; const [invite, setInvite] = useState<{ email: string; company_name?: string; name?: string } | null>(null); const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [error, setError] = useState(""); const [done, setDone] = useState(false); const [loading, setLoading] = useState(true); useEffect(() => { if (!token) { setError("Invite token is missing."); setLoading(false); return; } fetch(`/api/invites?token=${encodeURIComponent(token)}`).then(async (response) => { if (!response.ok) throw new Error((await response.json()).error || "Invite is invalid or expired"); setInvite((await response.json()).invite); }).catch((reason) => setError(reason instanceof Error ? reason.message : "Invite could not be verified")).finally(() => setLoading(false)); }, [token]); async function activate(event: FormEvent) { event.preventDefault(); if (!neonClient || !invite) return; if (password.length < 8) { setError("Password must be at least 8 characters."); return; } if (password !== confirm) { setError("Passwords do not match."); return; } setLoading(true); setError(""); const result = await neonClient.auth.signUp.email({ name: invite.name || invite.email.split("@")[0], email: invite.email, password }); if (result.error) { setError(result.error.message || "Account could not be activated."); setLoading(false); return; } const tokenResponse = await fetch("/api/invites", { method: "POST", headers: { "content-type": "application/json", ...(await getNeonToken() ? { Authorization: `Bearer ${await getNeonToken()}` } : {}) }, body: JSON.stringify({ action: "consume", token }) }); if (!tokenResponse.ok) { setError("Account created, but invite confirmation failed. Please contact Hermes."); setLoading(false); return; } setDone(true); setLoading(false); } if (loading && !invite) return <SkeletonDashboard full />; if (done) return <div className="login-shell"><div className="login-card"><BrandMark /><p className="eyebrow">HERMES SOFTWARE / ACCESS READY</p><h1>You're in.<br /><span>Let's ship.</span></h1><p className="muted">Your account is active. Return to the portal and sign in with your new password.</p><a className="button button-green wide" href="/">ENTER PORTAL <ChevronDown size={16} /></a></div></div>; return <div className="login-shell"><form className="login-card" onSubmit={activate}><BrandMark /><p className="eyebrow">HERMES SOFTWARE / CLIENT INVITE</p><h1>Set your<br /><span>password.</span></h1>{error ? <p className="login-error">{error}</p> : <p className="muted">{invite?.company_name || "Your Hermes workspace"} · {invite?.email}</p>}<label className="login-label">PASSWORD<input type="password" minLength={8} required value={password} onChange={(event) => setPassword(event.target.value)} placeholder="At least 8 characters" /></label><label className="login-label">CONFIRM PASSWORD<input type="password" minLength={8} required value={confirm} onChange={(event) => setConfirm(event.target.value)} placeholder="Repeat your password" /></label><button className="button button-green wide" disabled={loading}>{loading ? "ACTIVATING…" : "ACTIVATE ACCOUNT"} <ChevronDown size={16} /></button><small>This invite is single-use and expires in 7 days.</small></form></div>; }

function App() { useEffect(() => { if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => undefined); }, []); if (window.location.pathname === "/activate") return <ActivationPage />; if (!neonConfigured) return <PortalApp />; return <NeonAuthApp />; }
function NeonAuthApp() { const [user, setUser] = useState<{ name?: string; email?: string } | null>(null); const [loading, setLoading] = useState(true); useEffect(() => { neonClient?.auth.getSession().then((result) => { setUser(result.data?.user || null); setLoading(false); }); }, []); if (loading) return <SkeletonDashboard full />; if (!user) return <DemoLogin />; return <PortalApp userName={user.name || user.email || "Client"} onLogout={async () => { await neonClient?.auth.signOut(); setUser(null); }} />; }

function PortalApp({ userName = "Client", onLogout }: { userName?: string; onLogout?: () => void }) {
  const initialSection = window.location.pathname === "/admin" ? "Overview" : "Dashboard";
  const [section, setSection] = useState(initialSection); const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null); const [profileOpen, setProfileOpen] = useState(false); const [language, setLanguage] = useState<"en" | "tr">(() => localStorage.getItem("hermes-language") === "tr" ? "tr" : "en"); const [mobileNav, setMobileNav] = useState(false); const [toast, setToast] = useState(""); const [admin, setAdmin] = useState(false); const [role, setRole] = useState("client"); const [projects, setProjects] = useState<Project[]>([]); const [clients, setClients] = useState<Client[]>([]); const [approvals, setApprovals] = useState<Approval[]>([]); const [payments, setPayments] = useState<Payment[]>([]); const [paymentSummary, setPaymentSummary] = useState<PaymentSummary>({ total_paid: 0, monthly_minimum: 0, total_value: 0, total_remaining: 0 }); const [loading, setLoading] = useState(true); const [loadError, setLoadError] = useState("");
  const clientNav = [["Dashboard", LayoutDashboard], ["Projects", ClipboardList], ["Approvals", ShieldCheck], ["Payments", CreditCard], ["Invoices", FileText], ["Files", FolderOpen], ["Messages", MessageSquare], ["Profile", Users]] as const; const adminNav = [["Overview", LayoutDashboard], ["Clients", Users], ["Projects", ClipboardList], ["Approvals", ShieldCheck], ["Payments", CircleDollarSign], ["Invoices", FileText], ["Milestones", ClipboardList], ["Files", FolderOpen], ["Activity", ShieldCheck], ["Settings", Settings]] as const;
  useEffect(() => { localStorage.setItem("hermes-language", language); document.documentElement.lang = language; }, [language]);
  useEffect(() => { let active = true; (async () => { try { const me = await apiFetch("/api/me"); if (!me.ok) { if (me.status === 403) { await onLogout?.(); return; } throw new Error(`Profile API failed (${me.status})`); } const meData = await me.json(); const projectsResponse = await apiFetch("/api/projects"); if (!projectsResponse.ok) throw new Error(`Projects API failed (${projectsResponse.status})`); const projectData = await projectsResponse.json(); const approvalResponse = await apiFetch("/api/approvals"); const approvalData = approvalResponse.ok ? await approvalResponse.json() : { approvals: [] }; const paymentResponse = await apiFetch("/api/payments"); const paymentData = paymentResponse.ok ? await paymentResponse.json() : { payments: [], summary: { total_paid: 0, monthly_minimum: 0, total_value: 0, total_remaining: 0 } }; const isAdmin = meData.user?.role === "admin"; let clientData: Client[] = []; if (isAdmin) { const clientsResponse = await apiFetch("/api/clients"); if (clientsResponse.ok) clientData = (await clientsResponse.json()).clients || []; } if (active) { setRole(meData.user?.role || "client"); setProjects(projectData.projects || []); setPayments(paymentData.payments || []); setPaymentSummary(paymentData.summary); setClients(clientData); setApprovals(approvalData.approvals || []); setAdmin(isAdmin); } } catch (error) { if (active) setLoadError(error instanceof Error ? error.message : "Portal data failed to load"); } finally { if (active) setLoading(false); } })(); return () => { active = false; }; }, []);
  const nav = admin ? adminNav : clientNav; const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2600); }; const refresh = async () => { const response = await apiFetch("/api/projects"); if (response.ok) setProjects((await response.json()).projects || []); }; const refreshPayments = async () => { const response = await apiFetch("/api/payments"); if (response.ok) { const data = await response.json(); setPayments(data.payments || []); setPaymentSummary(data.summary); } }; const refreshClients = async () => { const response = await apiFetch("/api/clients"); if (response.ok) setClients((await response.json()).clients || []); };
  return <div className="portal"><aside className={`sidebar ${mobileNav ? "open" : ""}`}><div className="side-brand"><BrandMark small /><span>HERMES<br /><b>PORTAL</b></span><button className="mobile-close" onClick={() => setMobileNav(false)}><X size={18} /></button></div><div className="side-label">WORKSPACE</div><nav>{nav.map(([label, Icon]) => <button key={label} className={section === label ? "active" : ""} onClick={() => { setSection(label); setMobileNav(false); setProfileOpen(false); }}><Icon size={17} />{uiLabel(label, language)}</button>)}</nav><div className="sidebar-bottom">{role === "admin" && <button onClick={() => setAdmin(!admin)}><ShieldCheck size={17} />{admin ? "Client view" : "Admin view"}</button>}<button onClick={onLogout || (() => notify("Sign out is available after authentication."))}><LogOut size={17} />Sign out</button></div></aside><main className="main"><header className="topbar"><button className="mobile-menu" onClick={() => setMobileNav(true)}><Menu size={20} /></button><div><p className="eyebrow">{admin ? "ADMIN / HERMES SOFTWARE" : `HELLO, ${userName.toUpperCase()}`}</p><h2>{uiLabel(section, language)}</h2></div><div className="top-actions"><div className="language-switch" role="group" aria-label="Language"><button className={language === "en" ? "active" : ""} onClick={() => setLanguage("en")}>EN</button><button className={language === "tr" ? "active" : ""} onClick={() => setLanguage("tr")}>TR</button></div><button className="icon-button" onClick={() => notify(language === "en" ? "You’re all caught up." : "Tüm bildirimler okundu.")}><Bell size={18} /></button><div className="profile-wrap"><button className="user-chip profile-trigger" onClick={() => setProfileOpen(!profileOpen)} aria-expanded={profileOpen}><span className="avatar">{userName.slice(0, 1).toUpperCase()}</span><span>{userName}</span><ChevronDown size={14} /></button>{profileOpen && <div className="profile-menu"><div className="profile-menu-head"><b>{userName}</b><small>{language === "en" ? "English interface" : "Türkçe arayüz"}</small></div><button onClick={() => { setLanguage("en"); setProfileOpen(false); }}>English <span>{language === "en" ? "✓" : ""}</span></button><button onClick={() => { setLanguage("tr"); setProfileOpen(false); }}>Türkçe <span>{language === "tr" ? "✓" : ""}</span></button><div className="profile-menu-line" /><button className="profile-logout" onClick={() => { setProfileOpen(false); onLogout?.(); }}><LogOut size={15} /> {language === "en" ? "Sign out" : "Çıkış yap"}</button></div>}</div></div></header><div className="content">{loadError && <div className="notice error"><b>{loadError}</b><br /><small>Auth session token could not reach the server. Refresh after signing in again.</small></div>}{loading ? <SkeletonDashboard /> : admin ? <AdminView section={section} projects={projects} clients={clients} approvals={approvals} payments={payments} paymentSummary={paymentSummary} language={language} setLanguage={setLanguage} notify={notify} onRefresh={refresh} onRefreshPayments={refreshPayments} onRefreshClients={refreshClients} /> : <ClientView section={section} projects={projects} payments={payments} approvals={approvals} paymentSummary={paymentSummary} notify={notify} selectedProjectId={selectedProjectId} onOpenProject={(id) => { setSelectedProjectId(id); setSection("Project Detail"); }} />}</div></main>{toast && <div className="toast">{toast}</div>}</div>;
}

function ApprovalView({ admin = false, projects, initialApprovals, notify }: { admin?: boolean; projects: Project[]; initialApprovals: Approval[]; notify: (message: string) => void }) { const [approvals, setApprovals] = useState<Approval[]>(initialApprovals); const [selected, setSelected] = useState<Approval | null>(null); const [saving, setSaving] = useState(false); const [readToEnd, setReadToEnd] = useState(false); const [readConfirmed, setReadConfirmed] = useState(false); const [legalAccepted, setLegalAccepted] = useState(false); const [signatureName, setSignatureName] = useState(""); const [editorMode, setEditorMode] = useState<"write" | "preview">("write"); const [draft, setDraft] = useState({ projectId: projects[0]?.id || "", title: "", content: "" }); function insertMarkdown(prefix: string, suffix = "") { setDraft((current) => ({ ...current, content: `${current.content}${current.content ? "\n\n" : ""}${prefix}${suffix}` })); setEditorMode("write"); } async function refresh() { const response = await apiFetch("/api/approvals"); if (response.ok) setApprovals((await response.json()).approvals || []); } async function create(event: FormEvent) { event.preventDefault(); setSaving(true); const response = await apiFetch("/api/approvals", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(draft) }); setSaving(false); if (!response.ok) { notify(`Approval request failed (${response.status}).`); return; } setDraft({ projectId: projects[0]?.id || "", title: "", content: "" }); await refresh(); notify("Approval request created."); } function open(item: Approval) { setSelected(item); setReadToEnd(false); setReadConfirmed(Boolean(item.read_confirmed_at)); setLegalAccepted(false); setSignatureName(""); } async function confirmReading() { if (!selected || !readToEnd) return; setSaving(true); const response = await apiFetch("/api/approvals", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: selected.id, action: "read", readConfirmed: true }) }); setSaving(false); if (!response.ok) { notify(`Reading confirmation failed (${response.status}).`); return; } setReadConfirmed(true); setSelected({ ...selected, read_confirmed_at: new Date().toISOString() }); notify("Reading recorded. Complete the final acceptance below."); } async function approve() { if (!selected || !readConfirmed || !legalAccepted || !signatureName.trim()) return; setSaving(true); const response = await apiFetch("/api/approvals", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: selected.id, action: "approve", confirmed: true, legalAccepted: true, signatureName: signatureName.trim() }) }); setSaving(false); if (!response.ok) { notify(`Approval failed (${response.status}).`); return; } await refresh(); setSelected(null); notify("Document approved and audit record sealed."); } if (selected) return <section className="approval-document"><div className="hero-row"><div><p className="eyebrow">DIGITAL APPROVAL / {selected.status.toUpperCase()}</p><h1>{selected.title}</h1><p className="muted">{selected.project_name || "Project document"} · SHA-256 {selected.content_hash.slice(0, 16)}…</p></div><button className="button button-dark" onClick={() => window.print()}>PRINT / SAVE PDF</button></div><article className="panel approval-paper" onScroll={(event) => { const element = event.currentTarget; if (element.scrollTop + element.clientHeight >= element.scrollHeight - 8) setReadToEnd(true); }}><div className="approval-paper-head"><b>HERMES SOFTWARE INC.</b><span>{selected.document_type.replaceAll("_", " ").toUpperCase()}</span></div><div className="approval-markdown" dangerouslySetInnerHTML={{ __html: selected.content_html || "<p>Document content unavailable.</p>" }} /><div className="approval-legal-notice"><b>LEGAL NOTICE / HUKUKİ BİLGİLENDİRME</b><p>{selected.legal_notice || "Bu işlem nitelikli elektronik imza değildir. Portal üzerinde yapılan dijital onay, belgeyi okuduğunuza ve kabul iradenize ilişkin elektronik kayıt oluşturur."}</p><small>Terms version: {selected.terms_version || "hermes-digital-approval-v1"}</small></div>{selected.status === "pending" && !admin && <div className="approval-steps"><div className={`approval-step ${readToEnd ? "complete" : ""}`}><span>1</span><div><b>READ THE COMPLETE DOCUMENT</b><small>{readToEnd ? "End of document reached." : "Scroll to the end to continue."}</small></div></div><label className={`approval-check ${!readToEnd ? "disabled" : ""}`}><input type="checkbox" disabled={!readToEnd || readConfirmed} checked={readConfirmed} onChange={(event) => { if (event.target.checked) confirmReading(); }} /> I confirm that I have read the complete document.</label>{readConfirmed && <><div className="approval-step complete"><span>2</span><div><b>ACKNOWLEDGE THE LEGAL EFFECT</b><small>Confirm what this digital approval means.</small></div></div><label className="approval-check"><input type="checkbox" checked={legalAccepted} onChange={(event) => setLegalAccepted(event.target.checked)} /> I understand this is a digital approval record, not a qualified electronic signature, and I accept the document content.</label><div className="approval-step"><span>3</span><div><b>TYPE YOUR LEGAL NAME</b><small>Your account identity and typed declaration are recorded in the audit trail.</small></div></div><input className="approval-name-input" value={signatureName} onChange={(event) => setSignatureName(event.target.value)} placeholder="Full name" /><button className="button button-green wide" disabled={saving || !legalAccepted || !signatureName.trim()} onClick={approve}>{saving ? "SEALING…" : "FINAL APPROVAL"}</button></>}</div>}{selected.status === "approved" && <div className="notice approval-sealed"><b>APPROVED / AUDIT SEALED</b><p>{selected.approved_by_name} · {selected.approved_at ? new Date(selected.approved_at).toLocaleString("tr-TR") : "—"}</p><small>Approval hash: {selected.approval_hash}</small></div>}</article><button className="text-button" onClick={() => setSelected(null)}>← BACK TO APPROVALS</button></section>; return <><section className="hero-row"><div><p className="eyebrow">WORKSPACE / DIGITAL APPROVALS</p><h1>{admin ? "Request approval." : "Your approvals."}</h1><p className="muted">{admin ? "Create a versioned document and request a multi-step client acceptance." : "Read, acknowledge and approve project documents with a traceable audit record."}</p></div></section>{admin && <form className="panel approval-form" onSubmit={create}><div className="panel-heading"><div><p className="eyebrow">NEW REQUEST</p><h3>Prepare a document</h3></div><span className="status-pill yellow">FREE DIGITAL APPROVAL</span></div><div className="approval-form-grid"><label className="login-label">PROJECT<select required value={draft.projectId} onChange={(event) => setDraft({ ...draft, projectId: event.target.value })}>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label className="login-label">TITLE<input required value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} placeholder="Website scope approval" /></label></div><div className="editor-head"><label className="login-label">DOCUMENT CONTENT</label><div className="editor-tabs"><button type="button" className={editorMode === "write" ? "active" : ""} onClick={() => setEditorMode("write")}>WRITE MD</button><button type="button" className={editorMode === "preview" ? "active" : ""} onClick={() => setEditorMode("preview")}>PREVIEW</button></div></div><div className="markdown-toolbar"><button type="button" onClick={() => insertMarkdown("# ")}>H1</button><button type="button" onClick={() => insertMarkdown("## ")}>H2</button><button type="button" onClick={() => insertMarkdown("- ")}>LIST</button><button type="button" onClick={() => insertMarkdown("**", "**")}>BOLD</button><button type="button" onClick={() => insertMarkdown("\n---\n")}>DIVIDER</button><button type="button" className="template-button" onClick={() => setDraft({ ...draft, content: "# Project Approval\n\n## Scope\n- Deliverable 1\n- Deliverable 2\n\n## Acceptance\nPlease review the scope above and confirm your approval." })}>USE TEMPLATE</button></div>{editorMode === "write" ? <textarea className="markdown-editor" required minLength={20} value={draft.content} onChange={(event) => setDraft({ ...draft, content: event.target.value })} placeholder="# Project Approval\n\nWrite the scope, delivery terms or acceptance text in Markdown..." /> : <div className="markdown-preview approval-markdown" dangerouslySetInnerHTML={{ __html: markdownPreview(draft.content) }} />}<button className="button button-green" disabled={saving}>{saving ? "CREATING…" : "REQUEST CLIENT APPROVAL"}</button></form>}<section className="panel"><div className="panel-heading"><div><p className="eyebrow">AUDITABLE RECORDS / {approvals.length}</p><h3>{admin ? "Approval requests" : "Documents waiting for you"}</h3></div><span className="status-pill green">HASHED</span></div>{approvals.length ? <div className="approval-list">{approvals.map((item) => <button className="approval-row" key={item.id} onClick={() => open(item)}><span className="approval-icon"><ShieldCheck size={18} /></span><span><b>{item.title}</b><small>{item.project_name || "Project"} · {new Date(item.requested_at).toLocaleDateString("tr-TR")}</small></span><span className={`status-pill ${item.status === "approved" ? "green" : "yellow"}`}>{item.status.toUpperCase()}</span></button>)}</div> : <div className="empty-state"><h3>No approval requests yet.</h3><p className="muted">New project documents will appear here.</p></div>}</section></>; }

function ClientView({ section, projects, payments, approvals, paymentSummary, notify, selectedProjectId, onOpenProject }: { section: string; projects: Project[]; payments: Payment[]; approvals: Approval[]; paymentSummary: PaymentSummary; notify: (message: string) => void; selectedProjectId: string | null; onOpenProject: (id: string) => void }) { if (section === "Project Detail") return <ProjectDetailView project={projects.find((item) => item.id === selectedProjectId)} payments={payments.filter((payment) => payment.project_id === selectedProjectId)} />; if (section === "Approvals") return <ApprovalView admin={false} projects={projects} initialApprovals={approvals} notify={notify} />; if (section === "Invoices") return <ClientInvoiceView />; if (section === "Profile") return <ProfileView />; if (section === "Payments") return <PaymentView admin={false} projects={projects} payments={payments} summary={paymentSummary} notify={notify} onRefresh={async () => {}} />; if (section === "Projects") return <WorkspaceSection title="Projects" eyebrow="WORKSPACE / PROJECTS" copy="Every engagement, status and delivery milestone in one place." projects={projects} action="OPEN PROJECT" onOpenProject={onOpenProject} />; if (section === "Files") return <WorkspaceSection title="Files" eyebrow="WORKSPACE / FILES" copy="Project files will appear here as Hermes shares deliverables." projects={projects} action="REQUEST FILE" onOpenProject={onOpenProject} />; if (section === "Messages") return <WorkspaceSection title="Messages" eyebrow="WORKSPACE / MESSAGES" copy="Keep project decisions and next steps in one clean thread." projects={projects} action="MESSAGE HERMES" onOpenProject={onOpenProject} />; const item = projects[0]; if (!item) return <div className="empty-state"><p className="eyebrow">NO ACTIVE PROJECTS</p><h1>Your workspace is ready.</h1><p className="muted">Hermes will add your first project here when the engagement starts.</p></div>; const total = Number(item.total_price || 0); const paid = Number(item.amount_paid || 0); const remaining = Number(item.remaining_balance ?? total - paid); return <><section className="hero-row"><div><p className="eyebrow">ACTIVE PROJECT / {item.company_name || "HERMES CLIENT"}</p><h1>{item.name}</h1><p className="muted">{statusLabel[item.status]} · live from your Hermes workspace.</p></div><button className="button button-dark" onClick={() => openWhatsApp(`Merhaba Hermes, ${item.name} projem hakkında görüşmek istiyorum.`)}><MessageSquare size={16} /> MESSAGE HERMES</button></section><section className="grid-12"><div className="panel progress-panel span-8"><div className="panel-top"><div><p className="eyebrow">CURRENT STATUS</p><h3>{statusLabel[item.status]}</h3></div><span className="status-pill green">LIVE</span></div><div className="progress-number">{item.progress}<small>%</small></div><div className="progress-track"><span style={{ width: `${item.progress}%` }} /></div><div className="status-rail">{statusOrder.map((status) => <div key={status} className={statusOrder.indexOf(status) <= statusOrder.indexOf(item.status) ? "done" : ""}><i />{statusLabel[status]}</div>)}</div></div><div className="panel span-4 price-panel"><p className="eyebrow">PROJECT VALUE</p><div className="price">₺{total.toLocaleString("tr-TR")}</div><div className="money-line"><span>Paid</span><b>₺{paid.toLocaleString("tr-TR")}</b></div><div className="money-line"><span>Remaining</span><b className="green-text">₺{remaining.toLocaleString("tr-TR")}</b></div><div className="due-date">Financial totals calculated server-side</div></div></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">PROJECTS</p><h3>Your active work</h3></div><button className="text-button" onClick={() => notify(`${projects.length} project${projects.length === 1 ? "" : "s"} loaded.`)}>REFRESHED FROM NEON →</button></div><div className="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Progress</th><th>Balance</th></tr></thead><tbody>{projects.map((project) => <tr key={project.id}><td><b>{project.name}</b><small>{project.company_name || "Hermes client"}</small></td><td><span className="status-pill green">{statusLabel[project.status]}</span></td><td>{project.progress}%</td><td>₺{Number(project.remaining_balance || 0).toLocaleString("tr-TR")}</td></tr>)}</tbody></table></div></section></>; }

function ProfileView() { const language = localStorage.getItem("hermes-language") === "tr" ? "tr" : "en"; const [profile, setProfile] = useState({ name: "", email: "", phone: "" }); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(""); useEffect(() => { apiFetch("/api/me").then(async (response) => { if (response.ok) { const data = await response.json(); setProfile({ name: data.user?.name || "", email: data.user?.email || "", phone: data.user?.phone || "" }); } }); }, []); async function save(event: FormEvent) { event.preventDefault(); setSaving(true); setMessage(""); const response = await apiFetch("/api/me", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: profile.name, phone: profile.phone }) }); setSaving(false); setMessage(response.ok ? "Profile saved." : "Profile could not be saved."); } return <><section className="hero-row"><div><p className="eyebrow">{language === "en" ? "ACCOUNT / PROFILE" : "HESAP / PROFİL"}</p><h1>{language === "en" ? "Your profile." : "Profilin."}</h1><p className="muted">{language === "en" ? "Keep the contact details Hermes uses for project communication and individual invoices up to date." : "Hermes’in iletişim ve bireysel faturalarda kullandığı bilgileri güncel tut."}</p></div></section><section className="panel profile-panel"><form className="profile-form" onSubmit={save}><label className="login-label">{language === "en" ? "FULL NAME" : "AD SOYAD"}<input required maxLength={120} value={profile.name} onChange={(event) => setProfile({ ...profile, name: event.target.value })} placeholder="Name Surname" /></label><label className="login-label">{language === "en" ? "EMAIL" : "E-POSTA"}<input value={profile.email} readOnly /></label><label className="login-label">{language === "en" ? "PHONE" : "TELEFON"}<input type="tel" value={profile.phone} onChange={(event) => setProfile({ ...profile, phone: event.target.value })} placeholder="+90 5xx xxx xx xx" /></label><button className="button button-green" disabled={saving}>{saving ? (language === "en" ? "SAVING…" : "KAYDEDİLİYOR…") : (language === "en" ? "SAVE PROFILE" : "PROFİLİ KAYDET")}</button>{message && <p className="form-hint">{message}</p>}</form><div className="profile-note"><p className="eyebrow">{language === "en" ? "INVOICE DETAILS" : "FATURA BİLGİLERİ"}</p><h3>{language === "en" ? "Individual client record" : "Bireysel müşteri kaydı"}</h3><p className="muted">{language === "en" ? "Your invoice copy uses only your full name, phone number and email address. No additional company or tax fields are required." : "Fatura kopyanda yalnızca ad soyad, telefon ve e-posta kullanılır."}</p></div></section></>; }

function InvoicePreview({ invoice, projectName = "Selected project", amount = "0", dueDate = "", admin = false }: { invoice?: Invoice; projectName?: string; amount?: string; dueDate?: string; admin?: boolean }) { const current = invoice || { number: "DRAFT PREVIEW", project_name: projectName, amount, due_date: dueDate || "—", issued_at: new Date().toISOString().slice(0, 10), status: "draft", customer_name: "Individual client", customer_email: "—", customer_phone: "—", currency: "TRY" } as Invoice; return <section className="panel invoice-paper invoice-preview-direct"><div className="invoice-preview-bar"><p className="eyebrow">{admin ? "LIVE PREVIEW / ADMIN" : "LIVE PREVIEW / CLIENT COPY"}</p><button className="button button-dark compact" onClick={() => window.print()}>PRINT / SAVE PDF</button></div><div className="invoice-header"><div><p className="eyebrow">HERMES SOFTWARE INC.</p><h2>INVOICE</h2></div><span className={`status-pill ${current.status === "paid" ? "green" : "yellow"}`}>{String(current.status).toUpperCase()}</span></div><div className="invoice-company"><b>Hermes Software Bilişim Teknolojileri Anonim Şirketi</b><span>Trade Registry: 0-204471-5 · MERSİS: 0687342100100017</span><span>Tax ID: 6870342198 · Boğaziçi VD — Beşiktaş</span><span>NACE 62.01 — Bilgisayar Programlama Faaliyetleri</span></div><div className="invoice-meta-grid"><div><small>INVOICE NO.</small><b>{current.number}</b></div><div><small>ISSUED</small><b>{current.issued_at || "—"}</b></div><div><small>DUE DATE</small><b>{current.due_date || "—"}</b></div></div><div className="invoice-preview-parties"><div><small>BILL TO</small><b>{current.customer_name || "Individual client"}</b><span>{current.customer_email || "—"}</span><span>{current.customer_phone || "—"}</span></div><div><small>PROJECT</small><b>{current.project_name || projectName}</b><span>Hermes Software delivery</span></div></div><div className="invoice-total-row"><span>TOTAL / {current.currency || "TRY"}</span><strong>₺{Number(current.amount || 0).toLocaleString("tr-TR", { minimumFractionDigits: 2 })}</strong></div><p className="invoice-legal-note">Draft preview only. Final tax/e-invoice submission must be completed through the company’s authorized accounting process.</p></section>; }

function ClientInvoiceView() { const [invoices, setInvoices] = useState<Invoice[]>([]); useEffect(() => { apiFetch("/api/invoices").then(async (response) => { if (response.ok) setInvoices((await response.json()).invoices || []); }); }, []); return <><section className="hero-row"><div><p className="eyebrow">FINANCE / INVOICES</p><h1>Your invoices.</h1><p className="muted">The latest invoice opens directly as a formal preview.</p></div></section>{invoices.length ? <InvoicePreview invoice={invoices[0]} /> : <section className="panel empty-state"><h3>No invoices yet.</h3><p className="muted">Your Hermes invoice records will appear here.</p></section>}</>; }

function ProjectDetailView({ project, payments }: { project?: Project; payments: Payment[] }) { const [milestones, setMilestones] = useState<Milestone[]>([]); const [activities, setActivities] = useState<Activity[]>([]); const [requestId, setRequestId] = useState<string | null>(null); const [requestText, setRequestText] = useState(""); const [message, setMessage] = useState(""); useEffect(() => { if (project) apiFetch(`/api/milestones?projectId=${activeProject.id}`).then(async (response) => { if (response.ok) { const data = await response.json(); setMilestones(data.milestones || []); setActivities(data.activities || []); } }); }, [project?.id]); if (!project) return <div className="empty-state"><h1>Project not found.</h1><p className="muted">Return to Projects and select an active project.</p></div>; const activeProject = project; const total = Number(project.total_price || 0); const paid = Number(project.amount_paid || payments.reduce((sum, item) => sum + Number(item.amount || 0), 0)); const remaining = Number(project.remaining_balance ?? total - paid); async function milestoneAction(id: string, action: "approve" | "request_changes", changeRequest?: string) { const response = await apiFetch("/api/milestones", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, action, changeRequest }) }); if (response.ok) { const refreshed = await apiFetch(`/api/milestones?projectId=${activeProject.id}`); if (refreshed.ok) { const data = await refreshed.json(); setMilestones(data.milestones || []); setActivities(data.activities || []); } setRequestId(null); setRequestText(""); setMessage(action === "approve" ? "Milestone approved." : "Change request sent."); } else setMessage("Could not update milestone."); } return <><section className="hero-row"><div><p className="eyebrow">PROJECT DETAIL / {project.company_name || "HERMES CLIENT"}</p><h1>{project.name}</h1><p className="muted">{statusLabel[project.status]} · {project.progress}% complete</p></div><button className="button button-dark" onClick={() => openWhatsApp(`Merhaba Hermes, ${project.name} projem hakkında görüşmek istiyorum.`)}><MessageSquare size={16} /> MESSAGE HERMES</button></section><section className="grid-12"><div className="panel progress-panel span-8"><div className="panel-top"><div><p className="eyebrow">DELIVERY STATUS</p><h3>{statusLabel[project.status]}</h3></div><span className="status-pill green">{project.progress}%</span></div><div className="progress-number">{project.progress}<small>%</small></div><div className="progress-track"><span style={{ width: `${project.progress}%` }} /></div><div className="status-rail">{statusOrder.map((status) => <div key={status} className={statusOrder.indexOf(status) <= statusOrder.indexOf(project.status) ? "done" : ""}><i />{statusLabel[status]}</div>)}</div></div><div className="panel span-4 price-panel"><p className="eyebrow">PROJECT VALUE</p><div className="price">₺{total.toLocaleString("tr-TR")}</div><div className="money-line"><span>Paid</span><b>₺{paid.toLocaleString("tr-TR")}</b></div><div className="money-line"><span>Remaining</span><b className="green-text">₺{remaining.toLocaleString("tr-TR")}</b></div></div></section><section className="grid-12"><div className="panel span-7"><div className="panel-heading"><div><p className="eyebrow">DELIVERY PLAN</p><h3>Milestones</h3></div><span className="status-pill yellow">{milestones.filter((item) => item.status === "approved" || item.status === "completed").length}/{milestones.length} approved</span></div>{milestones.length ? <div className="milestone-list">{milestones.map((item) => <div className="milestone-card" key={item.id}><div className="milestone-card-top"><div><b>{item.title}</b><small>{item.due_date ? `Due ${item.due_date}` : "No due date"}</small></div><span className={`status-pill ${item.status === "approved" || item.status === "completed" ? "green" : item.status === "changes_requested" ? "purple" : "yellow"}`}>{item.status.replace("_", " ").toUpperCase()}</span></div>{item.description && <p className="muted">{item.description}</p>}{item.change_request && <p className="change-request"><b>Change request:</b> {item.change_request}</p>}{item.status === "waiting_client" && <div className="milestone-actions"><button className="button button-green" onClick={() => milestoneAction(item.id, "approve")}>APPROVE</button><button className="button button-light" onClick={() => setRequestId(item.id)}>REQUEST CHANGES</button></div>}{requestId === item.id && <div className="change-form"><textarea value={requestText} onChange={(event) => setRequestText(event.target.value)} placeholder="Describe the changes you need" /><button className="button button-dark" onClick={() => milestoneAction(item.id, "request_changes", requestText)}>SEND REQUEST</button></div>}</div>)}</div> : <div className="empty-state"><h3>Milestones will appear here.</h3><p className="muted">Hermes will add the delivery plan to this project.</p></div>}{message && <p className="form-hint">{message}</p>}</div><div className="panel span-5"><div className="panel-heading"><div><p className="eyebrow">PROJECT ACTIVITY</p><h3>Timeline</h3></div></div>{activities.length ? <div className="timeline">{activities.map((item) => <div className="timeline-item" key={item.id}><span className="timeline-dot green" /><div><b>{item.title}</b><p>{item.body || item.kind} · {item.actor_name || "Hermes"}</p><small>{new Date(item.created_at).toLocaleString("en-GB")}</small></div></div>)}</div> : <p className="muted">Activity will appear as the project moves forward.</p>}</div></section><section className="grid-12"><div className="panel span-7"><div className="panel-heading"><div><p className="eyebrow">PAYMENTS</p><h3>{payments.length} recorded payment{payments.length === 1 ? "" : "s"}</h3></div></div><PaymentTable payments={payments} /></div><div className="panel span-5"><p className="eyebrow">NEXT STEP</p><h3>Need a change?</h3><p className="muted">Send the Hermes team a message with the project name already attached.</p><button className="button button-green wide" onClick={() => openWhatsApp(`Merhaba Hermes, ${project.name} projemde bir değişiklik talebim var.`)}>CONTACT HERMES</button></div></section></>; }

function WorkspaceSection({ title, eyebrow, copy, projects, action, onOpenProject }: { title: string; eyebrow: string; copy: string; projects: Project[]; action: string; onOpenProject: (id: string) => void }) { return <><section className="hero-row"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="muted">{copy}</p></div><button className="button button-green" onClick={() => openWhatsApp(`Merhaba Hermes, ${action.toLowerCase()} konusunda destek almak istiyorum.`)}><Plus size={16} /> {action}</button></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">LIVE FROM NEON</p><h3>{projects.length} project{projects.length === 1 ? "" : "s"}</h3></div></div>{projects.length ? <div className="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Progress</th><th>Next</th></tr></thead><tbody>{projects.map((project) => <tr key={project.id}><td><b>{project.name}</b><small>{project.company_name || "Hermes workspace"}</small></td><td><span className="status-pill green">{statusLabel[project.status]}</span></td><td>{project.progress}%</td><td><button className="text-button" onClick={() => onOpenProject(project.id)}>VIEW →</button></td></tr>)}</tbody></table></div> : <div className="empty-state"><h3>Nothing here yet.</h3><p className="muted">Your Hermes team will add content as the project moves forward.</p></div>}</section></>; }

function PaymentView({ admin, projects, payments, summary, notify, onRefresh }: { admin: boolean; projects: Project[]; payments: Payment[]; summary: PaymentSummary; notify: (message: string) => void; onRefresh: () => Promise<void> }) { const [projectId, setProjectId] = useState(projects[0]?.id || ""); const [amount, setAmount] = useState(""); const [monthlyMinimum, setMonthlyMinimum] = useState(String(projects[0]?.monthly_minimum || "")); const [method, setMethod] = useState("bank_transfer"); const [saving, setSaving] = useState(false); const selected = projects.find((project) => project.id === projectId); async function addPayment(event: FormEvent) { event.preventDefault(); if (!projectId) return; setSaving(true); const projectResponse = await apiFetch("/api/projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: projectId, monthlyMinimum: Number(monthlyMinimum || 0) }) }); const paymentResponse = amount ? await apiFetch("/api/payments", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId, amount: Number(amount), method }) }) : projectResponse; setSaving(false); if (!projectResponse.ok || !paymentResponse.ok) notify("Payment update failed."); else { setAmount(""); await onRefresh(); notify("Payment and monthly minimum saved."); } } if (!admin) return <><section className="hero-row"><div><p className="eyebrow">FINANCE / CLIENT VIEW</p><h1>Payments.</h1><p className="muted">A clear record of what has been paid and what remains.</p></div></section><div className="stats-grid"><div className="stat-card"><CreditCard size={19} /><p className="eyebrow">PAID</p><strong>₺{Number(summary.total_paid).toLocaleString("tr-TR")}</strong><span>Recorded payments</span></div><div className="stat-card"><CircleDollarSign size={19} /><p className="eyebrow">REMAINING</p><strong>₺{Number(summary.total_remaining).toLocaleString("tr-TR")}</strong><span>Across your projects</span></div><div className="stat-card"><FileText size={19} /><p className="eyebrow">MONTHLY MINIMUM</p><strong>₺{Number(summary.monthly_minimum).toLocaleString("tr-TR")}</strong><span>Agreed minimum</span></div></div><PaymentTable payments={payments} /></>; return <><section className="hero-row"><div><p className="eyebrow">FINANCE / ADMIN</p><h1>Money, clearly.</h1><p className="muted">Record payments and set the monthly minimum for every project.</p></div></section><div className="stats-grid"><div className="stat-card"><CreditCard size={19} /><p className="eyebrow">PAID</p><strong>₺{Number(summary.total_paid).toLocaleString("tr-TR")}</strong><span>All recorded payments</span></div><div className="stat-card"><CircleDollarSign size={19} /><p className="eyebrow">REMAINING</p><strong>₺{Number(summary.total_remaining).toLocaleString("tr-TR")}</strong><span>Outstanding balance</span></div><div className="stat-card"><FileText size={19} /><p className="eyebrow">MONTHLY MINIMUM</p><strong>₺{Number(summary.monthly_minimum).toLocaleString("tr-TR")}</strong><span>Configured across projects</span></div></div><section className="panel payment-form-panel"><div className="panel-heading"><div><p className="eyebrow">PAYMENT ENTRY</p><h3>Record a payment</h3></div></div><form className="payment-form" onSubmit={addPayment}><label className="login-label">PROJECT<select required value={projectId} onChange={(event) => { setProjectId(event.target.value); const next = projects.find((project) => project.id === event.target.value); setMonthlyMinimum(String(next?.monthly_minimum || "")); }}>{projects.map((project) => <option key={project.id} value={project.id}>{project.name} · {project.company_name || "Client"}</option>)}</select></label><label className="login-label">PAYMENT AMOUNT<input type="number" min="0" step="0.01" value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="0 = only update minimum" /></label><label className="login-label">MONTHLY MINIMUM<input type="number" min="0" step="0.01" value={monthlyMinimum} onChange={(event) => setMonthlyMinimum(event.target.value)} placeholder="15000" /></label><label className="login-label">METHOD<select value={method} onChange={(event) => setMethod(event.target.value)}><option value="bank_transfer">Bank transfer</option><option value="card">Card</option><option value="cash">Cash</option><option value="other">Other</option></select></label><button className="button button-green" disabled={saving}>{saving ? "SAVING…" : "SAVE PAYMENT"}</button></form>{selected && <p className="form-hint">Current balance: ₺{Number(selected.remaining_balance || 0).toLocaleString("tr-TR")} · Current minimum: ₺{Number(selected.monthly_minimum || 0).toLocaleString("tr-TR")}</p>}</section><PaymentTable payments={payments} /></>; }
function PaymentTable({ payments }: { payments: Payment[] }) { return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">PAYMENT HISTORY</p><h3>{payments.length} recorded payment{payments.length === 1 ? "" : "s"}</h3></div></div><div className="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Amount</th><th>Method</th><th>Date</th></tr></thead><tbody>{payments.map((payment) => <tr key={payment.id}><td><b>{payment.project_name}</b><small>{payment.reference || "Recorded payment"}</small></td><td>{payment.company_name}</td><td><b className="green-text">₺{Number(payment.amount).toLocaleString("tr-TR")}</b></td><td>{payment.method.replace("_", " ")}</td><td>{payment.paid_at}</td></tr>)}</tbody></table></div></section>; }

function urlBase64ToUint8Array(value: string) { const padding = "=".repeat((4 - value.length % 4) % 4); const base64 = (value + padding).replace(/-/g, "+").replace(/_/g, "/"); const raw = window.atob(base64); return Uint8Array.from([...raw].map((character) => character.charCodeAt(0))); }
function NotificationSettings({ notify }: { notify: (message: string) => void }) { const [enabled, setEnabled] = useState(false); const [supported, setSupported] = useState(true); const [busy, setBusy] = useState(false); useEffect(() => { setSupported("serviceWorker" in navigator && "PushManager" in window && "Notification" in window); }, []); async function toggle() { if (!supported) { notify("This browser does not support web push."); return; } setBusy(true); try { const settingsResponse = await apiFetch("/api/notifications"); const settings = await settingsResponse.json(); if (!settings.enabled || !settings.publicKey) throw new Error("Push server is not configured yet."); const registration = await navigator.serviceWorker.register("/sw.js"); if (Notification.permission === "denied") throw new Error("Notifications are blocked in browser settings."); const permission = await Notification.requestPermission(); if (permission !== "granted") throw new Error("Notification permission was not granted."); const existing = await registration.pushManager.getSubscription(); const subscription = existing || await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(settings.publicKey) }); const response = await apiFetch("/api/notifications", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "subscribe", subscription: subscription.toJSON() }) }); if (!response.ok) throw new Error("Subscription could not be saved."); setEnabled(true); notify("Push notifications enabled."); } catch (error) { notify(error instanceof Error ? error.message : "Push notification setup failed."); } finally { setBusy(false); } } async function disable() { setBusy(true); try { const registration = await navigator.serviceWorker.getRegistration("/"); const subscription = await registration?.pushManager.getSubscription(); if (subscription) { await apiFetch("/api/notifications", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "unsubscribe", endpoint: subscription.endpoint }) }); await subscription.unsubscribe(); } setEnabled(false); notify("Push notifications disabled."); } finally { setBusy(false); } } return <div className="settings-row notification-settings"><div><p className="eyebrow">PUSH NOTIFICATIONS</p><h3>{enabled ? "Notifications are on" : "Stay in the loop"}</h3><p className="muted">Get alerts for new approvals, invoices, payments and project updates.</p></div><button className={`button ${enabled ? "button-light" : "button-orange"}`} disabled={busy || !supported} onClick={enabled ? disable : toggle}><Bell size={15} /> {busy ? "WORKING…" : enabled ? "TURN OFF" : "ENABLE"}</button></div>; }
function SettingsView({ language, setLanguage, notify }: { language: "en" | "tr"; setLanguage: (language: "en" | "tr") => void; notify: (message: string) => void }) { return <><section className="hero-row"><div><p className="eyebrow">ADMIN / SETTINGS</p><h1>{language === "en" ? "Settings." : "Ayarlar."}</h1><p className="muted">{language === "en" ? "Control the workspace language and your portal preferences." : "Çalışma alanı dilini ve portal tercihlerini yönet."}</p></div></section><section className="panel settings-panel"><div className="settings-row"><div><p className="eyebrow">INTERFACE LANGUAGE</p><h3>{language === "en" ? "English" : "Türkçe"}</h3><p className="muted">English is the default main stream language.</p></div><div className="language-toggle"><button className={language === "en" ? "selected" : ""} onClick={() => { setLanguage("en"); notify("English interface enabled."); }}>ENGLISH</button><button className={language === "tr" ? "selected" : ""} onClick={() => { setLanguage("tr"); notify("Türkçe arayüz etkin."); }}>TÜRKÇE</button></div></div><NotificationSettings notify={notify} /><div className="settings-row"><div><p className="eyebrow">PORTAL STATUS</p><h3>Production workspace</h3><p className="muted">Auth, Neon data and protected routes are connected.</p></div><span className="status-pill green">LIVE</span></div></section></>; }

function InvoiceView({ projects, notify }: { projects: Project[]; notify: (message: string) => void }) { const [invoices, setInvoices] = useState<Invoice[]>([]); const [projectId, setProjectId] = useState(projects[0]?.id || ""); const [amount, setAmount] = useState(""); const [dueDate, setDueDate] = useState(""); const [saving, setSaving] = useState(false); useEffect(() => { apiFetch("/api/invoices").then(async (response) => { if (response.ok) setInvoices((await response.json()).invoices || []); }); }, []); async function createInvoice(event: FormEvent) { event.preventDefault(); setSaving(true); const response = await apiFetch("/api/invoices", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId, amount: Number(amount), dueDate }) }); setSaving(false); if (!response.ok) notify("Invoice could not be created."); else { setAmount(""); setDueDate(""); const refreshed = await apiFetch("/api/invoices"); if (refreshed.ok) setInvoices((await refreshed.json()).invoices || []); notify("Draft invoice created."); } } return <><section className="hero-row"><div><p className="eyebrow">ADMIN / INVOICES</p><h1>Official, clearly.</h1><p className="muted">Create a formal draft invoice using only Hermes Software’s registered company details.</p></div><button className="button button-dark" onClick={() => window.print()}>PRINT / SAVE PDF</button></section><section className="panel invoice-form-panel"><div className="panel-heading"><div><p className="eyebrow">NEW INVOICE</p><h3>Create draft</h3></div></div><form className="payment-form" onSubmit={createInvoice}><label className="login-label">PROJECT<select required value={projectId} onChange={(event) => setProjectId(event.target.value)}>{projects.map((project) => <option key={project.id} value={project.id}>{project.name} · {project.company_name || "Client"}</option>)}</select></label><label className="login-label">AMOUNT<input required type="number" min="0" step="0.01" value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="45000" /></label><label className="login-label">DUE DATE<input required type="date" value={dueDate} onChange={(event) => setDueDate(event.target.value)} /></label><button className="button button-green" disabled={saving}>{saving ? "CREATING…" : "CREATE DRAFT"}</button></form><p className="form-hint">This portal creates a draft record. Final tax/e-invoice submission and statutory requirements must be completed through the company’s authorized accounting process.</p></section><InvoicePreview projectName={projects.find((project) => project.id === projectId)?.name || "Selected project"} amount={amount} dueDate={dueDate} admin /><section className="panel invoice-paper"><div className="invoice-header"><div><p className="eyebrow">HERMES SOFTWARE INC.</p><h2>INVOICE</h2></div><span className="status-pill yellow">{invoices[0]?.status?.toUpperCase() || "DRAFT"}</span></div><div className="invoice-company"><b>Hermes Software Bilişim Teknolojileri Anonim Şirketi</b><span>Trade Registry: 0-204471-5 · MERSİS: 0687342100100017</span><span>Tax ID: 6870342198 · Boğaziçi VD — Beşiktaş</span><span>NACE 62.01 — Bilgisayar Programlama Faaliyetleri</span></div><div className="table-wrap"><table><thead><tr><th>Invoice No.</th><th>Project</th><th>Customer</th><th>Amount</th><th>Status</th></tr></thead><tbody>{invoices.map((invoice) => <tr key={invoice.id}><td><b>{invoice.number}</b><small>Issued {invoice.issued_at}</small></td><td>{invoice.project_name}</td><td><b>{invoice.customer_name}</b><small>{invoice.customer_email} · {invoice.customer_phone || "—"}</small></td><td><b>₺{Number(invoice.amount).toLocaleString("tr-TR")}</b><small>Due {invoice.due_date}</small></td><td><select className="status-select" value={invoice.status} onChange={async (event) => { const response = await apiFetch("/api/invoices", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: invoice.id, status: event.target.value }) }); if (response.ok) setInvoices((items) => items.map((item) => item.id === invoice.id ? { ...item, status: event.target.value, paid_at: event.target.value === "paid" ? new Date().toISOString().slice(0,10) : null } : item)); else notify("Invoice status update failed."); }}><option value="draft">DRAFT</option><option value="sent">SENT</option><option value="paid">PAID</option><option value="overdue">OVERDUE</option><option value="void">VOID</option></select></td></tr>)}</tbody></table></div></section></>; }

function MilestoneAdminView({ projects, notify }: { projects: Project[]; notify: (message: string) => void }) { const [projectId, setProjectId] = useState(projects[0]?.id || ""); const [items, setItems] = useState<Milestone[]>([]); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [dueDate, setDueDate] = useState(""); const [status, setStatus] = useState("not_started"); async function load(id = projectId) { if (!id) return; const response = await apiFetch(`/api/milestones?projectId=${id}`); if (response.ok) setItems((await response.json()).milestones || []); } useEffect(() => { load(); }, [projectId]); async function create(event: FormEvent) { event.preventDefault(); const response = await apiFetch("/api/milestones", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId, title, description, dueDate, status, sortOrder: items.length }) }); if (response.ok) { setTitle(""); setDescription(""); setDueDate(""); await load(); notify("Milestone created."); } else notify("Milestone creation failed."); } async function update(id: string, nextStatus: string) { const response = await apiFetch("/api/milestones", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, status: nextStatus }) }); if (response.ok) setItems((current) => current.map((item) => item.id === id ? { ...item, status: nextStatus } : item)); else notify("Milestone update failed."); } return <><section className="hero-row"><div><p className="eyebrow">ADMIN / MILESTONES</p><h1>Ship with clarity.</h1><p className="muted">Set the delivery plan, then let the client approve or request changes from their project view.</p></div></section><section className="panel milestone-admin-panel"><label className="login-label">PROJECT<select value={projectId} onChange={(event) => setProjectId(event.target.value)}>{projects.map((project) => <option key={project.id} value={project.id}>{project.name} · {project.company_name || "Client"}</option>)}</select></label><form className="milestone-create-form" onSubmit={create}><label className="login-label">MILESTONE<input required value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Design review" /></label><label className="login-label">DUE DATE<input type="date" value={dueDate} onChange={(event) => setDueDate(event.target.value)} /></label><label className="login-label">STATUS<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="internal_review">Internal review</option><option value="waiting_client">Waiting for client</option></select></label><label className="login-label milestone-description">DESCRIPTION<textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What will be delivered?" /></label><button className="button button-green">ADD MILESTONE</button></form></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">DELIVERY PLAN</p><h3>{items.length} milestones</h3></div></div>{items.length ? <div className="milestone-list">{items.map((item) => <div className="milestone-card" key={item.id}><div className="milestone-card-top"><div><b>{item.title}</b><small>{item.due_date || "No due date"}</small></div><select className="status-select" value={item.status} onChange={(event) => update(item.id, event.target.value)}><option value="not_started">NOT STARTED</option><option value="in_progress">IN PROGRESS</option><option value="internal_review">INTERNAL REVIEW</option><option value="waiting_client">WAITING CLIENT</option><option value="changes_requested">CHANGES REQUESTED</option><option value="approved">APPROVED</option><option value="completed">COMPLETED</option></select></div>{item.description && <p className="muted">{item.description}</p>}{item.change_request && <p className="change-request">Client: {item.change_request}</p>}</div>)}</div> : <div className="empty-state"><h3>No milestones yet.</h3><p className="muted">Create the first delivery checkpoint above.</p></div>}</section></>; }

function AdminToolView({ section, projects, payments, notify }: { section: string; projects: Project[]; payments: Payment[]; notify: (message: string) => void }) { const labels: Record<string,string> = { Invoices: "Track invoice status and connect each invoice to a project.", Files: "Private project files are staged here; R2 storage can be connected when needed.", Activity: "A chronological audit trail for project and admin activity.", Settings: "Workspace settings and operational preferences." }; const action = section === "Invoices" ? "CREATE INVOICE" : section === "Files" ? "UPLOAD FILE" : section === "Activity" ? "ADD UPDATE" : "SAVE SETTINGS"; return <><section className="hero-row"><div><p className="eyebrow">ADMIN / {section.toUpperCase()}</p><h1>{section}.</h1><p className="muted">{labels[section]}</p></div><button className="button button-green" onClick={() => notify(`${action} is ready in this workspace.`)}><Plus size={16} /> {action}</button></section><section className="grid-12"><div className="panel span-7"><div className="panel-heading"><div><p className="eyebrow">WORKSPACE DATA</p><h3>{section === "Invoices" ? `${projects.length} project invoices` : section === "Activity" ? "Recent activity" : section === "Files" ? "Project file space" : "Hermes controls"}</h3></div></div>{section === "Invoices" ? <div className="table-wrap"><table><thead><tr><th>Project</th><th>Invoice amount</th><th>Status</th></tr></thead><tbody>{projects.map((project) => <tr key={project.id}><td><b>{project.name}</b><small>{project.company_name || "Client"}</small></td><td>₺{Number(project.total_price || 0).toLocaleString("tr-TR")}</td><td><span className="status-pill yellow">DRAFT</span></td></tr>)}</tbody></table></div> : <div className="timeline"><div className="timeline-item"><span className="timeline-dot green" /><div><b>{section === "Activity" ? "Workspace activity is connected" : `${section} module is ready`}</b><p>Hermes Software · live workspace</p></div></div><div className="timeline-item"><span className="timeline-dot" /><div><b>{payments.length ? `${payments.length} payment records available` : "No records yet"}</b><p>Data is scoped to this portal</p></div></div></div>}</div><div className="panel span-5"><p className="eyebrow">HERMES NOTE</p><h3>Simple by default.</h3><p className="muted">This module is active and protected. Add the next record from the action above; data remains scoped to authorized accounts.</p></div></section></>; }

function AdminView({ section, projects, clients, approvals, payments, paymentSummary, language, setLanguage, notify, onRefresh, onRefreshPayments, onRefreshClients }: { section: string; projects: Project[]; clients: Client[]; approvals: Approval[]; payments: Payment[]; paymentSummary: PaymentSummary; language: "en" | "tr"; setLanguage: (language: "en" | "tr") => void; notify: (message: string) => void; onRefresh: () => Promise<void>; onRefreshPayments: () => Promise<void>; onRefreshClients: () => Promise<void> }) {
  const [editing, setEditing] = useState<Project | null>(null); const [editingClient, setEditingClient] = useState<Client | null>(null); const [showClientForm, setShowClientForm] = useState(false); const [showProjectForm, setShowProjectForm] = useState(false); const [saving, setSaving] = useState(false);
  const [projectDraft, setProjectDraft] = useState({ clientId: clients[0]?.id || "", name: "", summary: "", totalPrice: "", currency: "TRY" }); const [inviteUrl, setInviteUrl] = useState("");
  const cards = [{ label: "Active projects", value: String(projects.length), delta: "Live from Neon", icon: ClipboardList }, { label: "Outstanding", value: `₺${projects.reduce((sum, p) => sum + Number(p.remaining_balance || 0), 0).toLocaleString("tr-TR")}`, delta: "Calculated server-side", icon: CircleDollarSign }, { label: "Clients", value: String(clients.length), delta: "Manage accounts", icon: Users }, { label: "Files", value: "Optional", delta: "R2 not required", icon: FolderOpen }];
  async function saveProject(event: FormEvent) { event.preventDefault(); if (!editing) return; setSaving(true); const response = await apiFetch("/api/projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: editing.id, name: editing.name, status: editing.status, progress: editing.progress, totalPrice: editing.total_price, dueDate: editing.due_date }) }); setSaving(false); if (!response.ok) notify(`Project update failed (${response.status}).`); else { setEditing(null); await onRefresh(); notify("Project updated in Neon."); } }
  async function createProject(event: FormEvent) { event.preventDefault(); setSaving(true); const response = await apiFetch("/api/projects", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ clientId: projectDraft.clientId, name: projectDraft.name, summary: projectDraft.summary, totalPrice: Number(projectDraft.totalPrice || 0), currency: projectDraft.currency }) }); setSaving(false); if (!response.ok) notify(`Project create failed (${response.status}).`); else { setShowProjectForm(false); await onRefresh(); notify("Project created in Neon."); } }
  async function createInvite(clientId: string) { const response = await apiFetch("/api/invites", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ clientId }) }); if (!response.ok) { notify(`Invite creation failed (${response.status}).`); return; } setInviteUrl((await response.json()).inviteUrl); notify("Invite link ready. Send it via WhatsApp."); }
  async function saveClient(event: FormEvent) { event.preventDefault(); if (!editingClient) return; setSaving(true); const isNew = !editingClient.id; const response = await apiFetch("/api/clients", { method: isNew ? "POST" : "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: editingClient.id, email: editingClient.email, name: editingClient.name, companyName: editingClient.company_name, phone: editingClient.phone, notes: editingClient.notes }) }); if (!response.ok) { setSaving(false); notify(`Client save failed (${response.status}).`); return; } const data = await response.json(); if (isNew && data.client?.id) { const inviteResponse = await apiFetch("/api/invites", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ clientId: data.client.id }) }); if (inviteResponse.ok) setInviteUrl((await inviteResponse.json()).inviteUrl); else notify("Client saved, but invite link could not be created."); } setSaving(false); setShowClientForm(false); setEditingClient(null); await onRefreshClients(); notify(isNew ? "Client saved. Copy the invite link below." : "Client saved in Neon."); }
  if (section === "Settings") return <SettingsView language={language} setLanguage={setLanguage} notify={notify} />;
  if (section === "Approvals") return <ApprovalView admin projects={projects} initialApprovals={approvals} notify={notify} />; if (section === "Invoices") return <InvoiceView projects={projects} notify={notify} />;
  if (section === "Milestones") return <MilestoneAdminView projects={projects} notify={notify} />;
  if (["Files", "Activity"].includes(section)) return <AdminToolView section={section} projects={projects} payments={payments} notify={notify} />;
  if (section === "Payments") return <PaymentView admin projects={projects} payments={payments} summary={paymentSummary} notify={notify} onRefresh={async () => { await onRefresh(); await onRefreshPayments(); }} />;
  if (section === "Clients") return <><section className="hero-row"><div><p className="eyebrow">CRM / CLIENT ACCOUNTS</p><h1>People you ship with.</h1><p className="muted">Create and manage customer records here. Client access is invite-only; public self-signup is disabled.</p></div><button className="button button-green" onClick={() => { setInviteUrl(""); setEditingClient({ id: "", company_name: "", email: "", name: "" }); setShowClientForm(true); }}><Plus size={16} /> NEW CLIENT</button></section>{inviteUrl && <div className="notice invite-notice"><b>CLIENT INVITE READY</b><p>Send this one-time link to the client. It expires in 7 days.</p><div className="invite-copy-row"><input readOnly value={inviteUrl} /><button className="button button-orange" onClick={() => openWhatsApp(`Merhaba, Hermes Software client portal erişimin hazır. Hesabını aktifleştirmek ve kendi şifreni belirlemek için bu linki aç: ${inviteUrl}`)}>SEND VIA WHATSAPP</button><button className="button button-dark" onClick={() => { navigator.clipboard?.writeText(inviteUrl); notify("Invite link copied."); }}>COPY LINK</button></div></div>}<section className="panel"><div className="panel-heading"><div><p className="eyebrow">CLIENTS / {clients.length}</p><h3>Customer accounts</h3></div><div className="search-box"><Search size={15} /><input placeholder="Search clients" /></div></div><div className="table-wrap"><table><thead><tr><th>Contact</th><th>Company</th><th>Projects</th><th>Phone</th><th /></tr></thead><tbody>{clients.map((client) => <tr key={client.id}><td><b>{client.name}</b><small>{client.email}</small></td><td>{client.company_name}</td><td>{client.project_count || 0}</td><td>{client.phone || "—"}</td><td><div className="client-actions"><button className="button button-orange compact" onClick={() => createInvite(client.id)}><MessageSquare size={13} /> INVITE</button><button className="icon-button" onClick={() => { setEditingClient(client); setShowClientForm(true); }}><MoreHorizontal size={16} /></button></div></td></tr>)}</tbody></table></div></section>{showClientForm && editingClient && <ClientModal value={editingClient} setValue={setEditingClient} saving={saving} onClose={() => setShowClientForm(false)} onSubmit={saveClient} />}</>;
  return <><section className="hero-row"><div><p className="eyebrow">OPERATIONS / LIVE DATA</p><h1>Keep shipping.</h1><p className="muted">The studio, one clean view. Every number comes from Neon.</p></div><button className="button button-green" onClick={() => { if (!clients.length) { notify("Create a client first."); return; } setProjectDraft({ clientId: clients[0].id, name: "", summary: "", totalPrice: "", currency: "TRY" }); setShowProjectForm(true); }}><Plus size={16} /> NEW PROJECT</button></section><div className="stats-grid">{cards.map(({ label, value, delta, icon: Icon }) => <div className="stat-card" key={label}><Icon size={19} /><p className="eyebrow">{label}</p><strong>{value}</strong><span>{delta}</span></div>)}</div><section className="panel"><div className="panel-heading"><div><p className="eyebrow">PROJECTS / ALL CLIENTS</p><h3>Active work</h3></div><div className="search-box"><Search size={15} /><input placeholder="Search projects" /></div></div><div className="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Status</th><th>Progress</th><th>Balance</th><th /></tr></thead><tbody>{projects.map((item) => <tr key={item.id}><td><b>{item.name}</b><small>{statusLabel[item.status]}</small></td><td>{item.company_name || "—"}</td><td><span className="status-pill green">{statusLabel[item.status]}</span></td><td><div className="mini-progress"><span style={{ width: `${item.progress}%` }} /></div>{item.progress}%</td><td>₺{Number(item.remaining_balance || 0).toLocaleString("tr-TR")}</td><td><button className="icon-button" onClick={() => setEditing(item)}><MoreHorizontal size={16} /></button></td></tr>)}</tbody></table></div></section>{editing && <ProjectEditModal value={editing} setValue={setEditing} saving={saving} onClose={() => setEditing(null)} onSubmit={saveProject} />}{showProjectForm && <ProjectModal value={projectDraft} clients={clients} setValue={setProjectDraft} saving={saving} onClose={() => setShowProjectForm(false)} onSubmit={createProject} />}</>;
}

function ProjectEditModal({ value, setValue, saving, onClose, onSubmit }: { value: Project; setValue: (value: Project) => void; saving: boolean; onClose: () => void; onSubmit: (event: FormEvent) => void }) { return <div className="modal-backdrop"><form className="modal-card" onSubmit={onSubmit}><div className="panel-heading"><div><p className="eyebrow">EDIT PROJECT</p><h3>{value.name}</h3></div><button type="button" className="icon-button" onClick={onClose}><X size={17} /></button></div><label className="login-label">NAME<input value={value.name} onChange={(event) => setValue({ ...value, name: event.target.value })} /></label><label className="login-label">STATUS<select value={value.status} onChange={(event) => setValue({ ...value, status: event.target.value as ProjectStatus })}>{statusOrder.map((status) => <option key={status} value={status}>{statusLabel[status]}</option>)}</select></label><label className="login-label">PROGRESS<input type="number" min="0" max="100" value={value.progress} onChange={(event) => setValue({ ...value, progress: Number(event.target.value) })} /></label><button className="button button-green wide" disabled={saving}>{saving ? "SAVING…" : "SAVE TO NEON"}</button></form></div>; }

function ProjectModal({ value, clients, setValue, saving, onClose, onSubmit }: { value: { clientId: string; name: string; summary: string; totalPrice: string; currency: string }; clients: Client[]; setValue: (value: { clientId: string; name: string; summary: string; totalPrice: string; currency: string }) => void; saving: boolean; onClose: () => void; onSubmit: (event: FormEvent) => void }) { return <div className="modal-backdrop"><form className="modal-card" onSubmit={onSubmit}><div className="panel-heading"><div><p className="eyebrow">NEW PROJECT</p><h3>Start a project</h3></div><button type="button" className="icon-button" onClick={onClose}><X size={17} /></button></div><label className="login-label">CLIENT<select required value={value.clientId} onChange={(event) => setValue({ ...value, clientId: event.target.value })}>{clients.map((client) => <option key={client.id} value={client.id}>{client.company_name} · {client.name}</option>)}</select></label><label className="login-label">PROJECT NAME<input required value={value.name} onChange={(event) => setValue({ ...value, name: event.target.value })} placeholder="Website redesign" /></label><label className="login-label">SUMMARY<textarea value={value.summary} onChange={(event) => setValue({ ...value, summary: event.target.value })} placeholder="What are we shipping?" /></label><label className="login-label">TOTAL PRICE<input type="number" min="0" value={value.totalPrice} onChange={(event) => setValue({ ...value, totalPrice: event.target.value })} placeholder="45000" /></label><button className="button button-green wide" disabled={saving}>{saving ? "CREATING…" : "CREATE PROJECT"}</button></form></div>; }

function ClientModal({ value, setValue, saving, onClose, onSubmit }: { value: Client; setValue: (value: Client) => void; saving: boolean; onClose: () => void; onSubmit: (event: FormEvent) => void }) { return <div className="modal-backdrop"><form className="modal-card" onSubmit={onSubmit}><div className="panel-heading"><div><p className="eyebrow">{value.id ? "EDIT CLIENT" : "NEW CLIENT"}</p><h3>Client account</h3></div><button type="button" className="icon-button" onClick={onClose}><X size={17} /></button></div><label className="login-label">FULL NAME<input required value={value.name} onChange={(event) => setValue({ ...value, name: event.target.value })} /></label><label className="login-label">EMAIL<input required type="email" value={value.email} onChange={(event) => setValue({ ...value, email: event.target.value })} /></label><label className="login-label">COMPANY<input required value={value.company_name} onChange={(event) => setValue({ ...value, company_name: event.target.value })} /></label><label className="login-label">PHONE<input value={value.phone || ""} onChange={(event) => setValue({ ...value, phone: event.target.value })} /></label><label className="login-label">NOTES<textarea value={value.notes || ""} onChange={(event) => setValue({ ...value, notes: event.target.value })} /></label><button className="button button-green wide" disabled={saving}>{saving ? "SAVING…" : "SAVE CLIENT"}</button></form></div>; }

export default App;
